import { db } from "@/lib/db";
import type { BlogPost } from "@prisma/client";

export const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

/* ----------------------------------------------------------------------------
 * Fetch helpers
 * ------------------------------------------------------------------------- */

/** Published posts, newest first -- for the public blog index. */
export function getPublishedPosts(): Promise<BlogPost[]> {
  return db.blogPost.findMany({
    where: { published: true },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
  });
}

/** A single published post by slug, or null (drives notFound() on the page). */
export function getPublishedPost(slug: string): Promise<BlogPost | null> {
  return db.blogPost.findFirst({ where: { slug, published: true } });
}

/**
 * Full-text-ish search over published posts. Case-insensitive `contains` across
 * title / excerpt / body, plus an exact tag match. Empty query falls back to the
 * normal newest-first listing. Runs server-side so results are crawlable.
 */
export function searchPublishedPosts(q: string): Promise<BlogPost[]> {
  const query = q.trim();
  if (!query) return getPublishedPosts();
  return db.blogPost.findMany({
    where: {
      published: true,
      OR: [
        { title: { contains: query, mode: "insensitive" } },
        { excerpt: { contains: query, mode: "insensitive" } },
        { body: { contains: query, mode: "insensitive" } },
        { category: { contains: query, mode: "insensitive" } },
        { tags: { has: query.toLowerCase() } },
      ],
    },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
  });
}

/** Default page size for the paginated blog index. */
export const POSTS_PER_PAGE = 12;

/** Prisma `where` for the public index -- optionally narrowed by a search query. */
function publishedWhere(q?: string) {
  const query = (q ?? "").trim();
  if (!query) return { published: true } as const;
  return {
    published: true,
    OR: [
      { title: { contains: query, mode: "insensitive" as const } },
      { excerpt: { contains: query, mode: "insensitive" as const } },
      { body: { contains: query, mode: "insensitive" as const } },
      { category: { contains: query, mode: "insensitive" as const } },
      { tags: { has: query.toLowerCase() } },
    ],
  };
}

export type PostsPage = {
  posts: BlogPost[];
  total: number;
  page: number;
  totalPages: number;
  perPage: number;
};

/**
 * One page of published posts (newest first), optionally filtered by a search
 * query. `page` is 1-based and clamped into range. Returns the slice plus enough
 * metadata to render prev/next controls and per-page canonicals. Runs a single
 * count + a single findMany so the index stays light even with ~200 posts.
 */
export async function getPostsPage(opts: { page?: number; q?: string; perPage?: number } = {}): Promise<PostsPage> {
  const perPage = Math.max(1, opts.perPage ?? POSTS_PER_PAGE);
  const where = publishedWhere(opts.q);
  const total = await db.blogPost.count({ where });
  const totalPages = Math.max(1, Math.ceil(total / perPage));
  const page = Math.min(Math.max(1, Math.floor(opts.page ?? 1)), totalPages);
  const posts = await db.blogPost.findMany({
    where,
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    skip: (page - 1) * perPage,
    take: perPage,
  });
  return { posts, total, page, totalPages, perPage };
}

/**
 * Up to `limit` other published posts related to `post` -- same category first,
 * back-filled with the newest posts so the block is never short. The current
 * post is always excluded. Drives the "Related articles" internal-linking block
 * on the post page (the biggest lever for getting thin/orphaned posts indexed).
 */
export async function getRelatedPosts(post: BlogPost, limit = 3): Promise<BlogPost[]> {
  const sameCategory = await db.blogPost.findMany({
    where: { published: true, category: post.category, id: { not: post.id } },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    take: limit,
  });
  if (sameCategory.length >= limit) return sameCategory;

  // Back-fill with the newest posts, skipping anything already picked.
  const have = new Set([post.id, ...sameCategory.map((p) => p.id)]);
  const recent = await db.blogPost.findMany({
    where: { published: true, id: { notIn: [...have] } },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    take: limit - sameCategory.length,
  });
  return [...sameCategory, ...recent];
}

/**
 * Map a post to the single most relevant product page so every article funnels
 * to a money page (internal-linking + conversion). Matches the post's category,
 * tags and title against product keywords; falls back to the pricing page.
 */
export function productLinkForPost(post: BlogPost): { label: string; href: string; blurb: string } {
  const hay = `${post.category} ${post.tags.join(" ")} ${post.title}`.toLowerCase();
  const has = (...ks: string[]) => ks.some((k) => hay.includes(k));

  if (has("minecraft", "rust", "game", "valheim", "palworld", "ark", "fivem", "server hosting"))
    return {
      label: "Game server hosting",
      href: "/game-servers",
      blurb: "Spin up a ready-to-play game server in minutes -- one-click installs, DDoS protection and instant scaling.",
    };
  if (has("web hosting", "wordpress", "website", "php", "shared hosting"))
    return {
      label: "Web hosting",
      href: "/web-hosting",
      blurb: "Get your site online without managing a server -- PHP, databases, email and free SSL, from a few dollars a month.",
    };
  if (has("domain", "dns", "nameserver"))
    return {
      label: "Register a domain",
      href: "/domains",
      blurb: "Search and register your domain, with free DNS management and one-click connection to your Nxeon services.",
    };
  if (has("email", "mailbox", "smtp"))
    return {
      label: "Business email",
      href: "/business-email",
      blurb: "Professional mailboxes on your own domain, with webmail, IMAP and spam filtering included.",
    };
  // Default: VPS is the flagship product for everything else (Linux, security,
  // Docker, self-hosting).
  return {
    label: "Cloud VPS hosting",
    href: "/vps",
    blurb: "Full root access on NVMe cloud VPS with instant deployment -- the flexible way to host anything.",
  };
}

/** Every post regardless of status, newest edit first -- for the admin editor. */
export function getAllPosts(): Promise<BlogPost[]> {
  return db.blogPost.findMany({ orderBy: { updatedAt: "desc" } });
}

/** Look up any post by id (admin edit form). */
export function getPostById(id: string): Promise<BlogPost | null> {
  return db.blogPost.findUnique({ where: { id } });
}

/* ----------------------------------------------------------------------------
 * Formatting
 * ------------------------------------------------------------------------- */

export function formatDate(d: Date | string | null | undefined): string {
  if (!d) return "";
  const date = typeof d === "string" ? new Date(d) : d;
  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
}

/** Rough read-time estimate from the raw markdown body. */
export function readMinutes(body: string): number {
  const words = body.trim().split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 200));
}

/* ----------------------------------------------------------------------------
 * Tiny, self-contained markdown -> HTML renderer.
 *
 * No external dependency. Handles: # / ## / ### headings, **bold**, `code`,
 * fenced ``` code blocks, - / * and 1. lists, [links](url), and blank-line
 * separated paragraphs. HTML is escaped BEFORE any markdown is applied, and
 * inline code spans are protected so their contents are never re-processed.
 * Output carries Tailwind classes so it reads well on the dark theme (there is
 * no typography plugin installed).
 * ------------------------------------------------------------------------- */

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

const CLS = {
  h1: "mt-10 mb-4 text-3xl font-bold tracking-tight text-white",
  h2: "mt-10 mb-3 text-2xl font-bold tracking-tight text-white",
  h3: "mt-8 mb-2 text-xl font-semibold text-white",
  p: "mb-4 leading-relaxed text-slate-300",
  ul: "mb-5 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  ol: "mb-5 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  li: "leading-relaxed",
  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
  pre: "mb-5 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
  img: "w-full rounded-xl border border-white/10 shadow-lg shadow-black/20",
};

/** Allow only http(s) or root-relative image sources; reject everything else. */
function safeSrc(u: string): string {
  return /^(https?:\/\/|\/)/.test(u) ? u : "";
}

// Private-use sentinels wrap protected inline-code indices so they can never
// collide with ordinary digits in prose (e.g. "2 GB", "port 25565").
const S0 = "\uE000";
const S1 = "\uE001";

/** Inline markdown for a single run of text. */
function inline(text: string): string {
  const codes: string[] = [];
  // Protect inline code first.
  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
    codes.push(c);
    return `${S0}${codes.length - 1}${S1}`;
  });
  // Bold.
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
  // Underline (__text__) and highlight (==text==) -- additive syntax, no
  // existing caller uses either pattern today so there's nothing to collide
  // with. Highlight renders as a real <mark>, not just a color, so it still
  // reads correctly with a screen reader or in a copy-pasted plain-text quote.
  s = s.replace(/__([^_]+)__/g, '<u class="underline decoration-2 underline-offset-2">$1</u>');
  s = s.replace(/==([^=]+)==/g, '<mark class="rounded bg-brand-500/25 px-1 text-white">$1</mark>');
  // Inline images ![alt](url) -- MUST run before links (they share `[..](..)`).
  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_m, alt: string, u: string) => {
    const safe = safeSrc(u);
    if (!safe) return "";
    return `<img class="${CLS.img} my-6" src="${safe}" alt="${alt}" loading="lazy" />`;
  });
  // Links [text](url) -- only http(s), root-relative, or anchors are allowed.
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
    const safe = /^(https?:\/\/|\/|#)/.test(u) ? u : "#";
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${t}</a>`;
  });
  // Restore inline code.
  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
  return s;
}

/* ----------------------------------------------------------------------------
 * Article-aware renderer for the editorial blog template.
 *
 * Same block/inline grammar as renderMarkdown, but additionally:
 *   - gives every heading a stable, unique `id` so the sticky table-of-contents
 *     spine + scroll-spy can anchor to it,
 *   - returns the H2/H3 outline as a TOC, and
 *   - extracts any question-style heading (text ending in "?") + its following
 *     prose as an FAQ pair, for FAQ JSON-LD.
 *
 * Kept separate from renderMarkdown so the four other callers (admin docs,
 * announcements, what's-new) are completely untouched.
 * ------------------------------------------------------------------------- */

export type TocEntry = { id: string; label: string; level: 2 | 3 };
export type FaqEntry = { q: string; a: string };
export type RenderedArticle = { html: string; toc: TocEntry[]; faq: FaqEntry[] };

/** URL-safe, human-readable heading anchor. */
export function slugifyHeading(text: string): string {
  return (
    text
      .toLowerCase()
      .replace(/`[^`]*`/g, "")
      .replace(/[*_[\]()#]/g, "")
      .replace(/&[a-z]+;/g, "")
      .replace(/[^a-z0-9\s-]/g, "")
      .trim()
      .replace(/\s+/g, "-")
      .slice(0, 60)
      .replace(/^-+|-+$/g, "") || "section"
  );
}

/** Strip inline markdown down to plain text (for FAQ answers / meta). */
function plainInline(text: string): string {
  return text
    .replace(/`([^`]+)`/g, "$1")
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .trim();
}

/** First non-empty prose paragraph of a markdown body, as plain text. */
export function firstParagraph(md: string): string {
  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
  const buf: string[] = [];
  for (const line of lines) {
    const t = line.trim();
    if (!t) {
      if (buf.length) break;
      continue;
    }
    if (/^(#{1,3}\s|[-*]\s|\d+\.\s|```|---+$|!\[)/.test(t)) {
      if (buf.length) break;
      continue;
    }
    buf.push(t);
  }
  return plainInline(buf.join(" "));
}

export function renderMarkdown(md: string): string {
  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Blank line -- skip.
    if (!line.trim()) { i++; continue; }

    // Horizontal rule.
    if (/^---+$/.test(line.trim())) {
      out.push('<hr class="my-8 border-white/[0.08]" />');
      i++;
      continue;
    }

    // A RUN of 2+ consecutive standalone image lines (no blank line or other
    // content between them) becomes a horizontally scrollable, snap-to-item
    // carousel instead of one figure per line stacked vertically -- useful for
    // "here are 6 screenshots" or "here are the game covers we just added"
    // without needing any client-side JS: CSS scroll-snap does the paging.
    // A single standalone image (the common case -- one screenshot) still
    // falls through to the plain captioned-figure path below unchanged.
    {
      const imgLineRe = /^!\[([^\]]*)\]\(([^)]+)\)$/;
      if (imgLineRe.test(line.trim())) {
        const run: { alt: string; src: string }[] = [];
        let j = i;
        while (j < lines.length) {
          const m = lines[j].trim().match(imgLineRe);
          if (!m) break;
          const safe = safeSrc(m[2]);
          if (safe) run.push({ alt: esc(m[1]), src: safe });
          j++;
        }
        if (run.length >= 2) {
          out.push(
            `<div class="my-7 -mx-1 flex snap-x snap-mandatory gap-3 overflow-x-auto px-1 pb-2" ` +
              `style="scrollbar-width:thin">` +
              run
                .map(
                  (r) =>
                    `<figure class="flex-none snap-center" style="width:min(200px,55%)">` +
                      // Fixed height + object-fit:cover, not just a width cap -- a
                      // carousel mixes landscape screenshots (~16:9) and portrait
                      // game-cover art (~2:3); capping only width let a tall
                      // poster's natural aspect ratio blow the image out to
                      // near-full viewport height (found live 2026-09-14).
                      `<img class="${CLS.img}" style="height:260px;width:100%;object-fit:cover" src="${r.src}" alt="${r.alt}" loading="lazy" />` +
                      (r.alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${r.alt}</figcaption>` : "") +
                      `</figure>`,
                )
                .join("") +
              `</div>`,
          );
          i = j;
          continue;
        }
      }
    }

    // Standalone image line -> captioned figure (not wrapped in a paragraph).
    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
    if (img) {
      const safe = safeSrc(img[2]);
      if (safe) {
        const alt = esc(img[1]);
        out.push(
          `<figure class="my-7"><img class="${CLS.img}" src="${safe}" alt="${alt}" loading="lazy" />` +
            (alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${alt}</figcaption>` : "") +
            `</figure>`,
        );
        i++;
        continue;
      }
    }

    // Fenced code block.
    if (/^```/.test(line.trim())) {
      const buf: string[] = [];
      i++;
      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
      i++; // closing fence
      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
      continue;
    }

    // Headings.
    if (/^###\s+/.test(line)) { out.push(`<h3 class="${CLS.h3}">${inline(line.replace(/^###\s+/, ""))}</h3>`); i++; continue; }
    if (/^##\s+/.test(line))  { out.push(`<h2 class="${CLS.h2}">${inline(line.replace(/^##\s+/, ""))}</h2>`);  i++; continue; }
    if (/^#\s+/.test(line))   { out.push(`<h1 class="${CLS.h1}">${inline(line.replace(/^#\s+/, ""))}</h1>`);   i++; continue; }

    // Ordered list.
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
        i++;
      }
      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
      continue;
    }

    // Unordered list.
    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
        i++;
      }
      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
      continue;
    }

    // Paragraph -- gather until a blank line or block boundary.
    const para = [line];
    i++;
    while (
      i < lines.length &&
      lines[i].trim() &&
      !/^#{1,3}\s/.test(lines[i]) &&
      !/^\s*[-*]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !/^```/.test(lines[i].trim()) &&
      !/^---+$/.test(lines[i].trim())
    ) {
      para.push(lines[i]);
      i++;
    }
    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
  }

  return out.join("\n");
}

export function renderArticle(md: string): RenderedArticle {
  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  const toc: TocEntry[] = [];
  const faq: FaqEntry[] = [];
  const usedIds = new Set<string>();
  // A question-style heading whose following prose is still being collected.
  let pendingQ: { q: string; ans: string[] } | null = null;
  let i = 0;

  const uniqueId = (base: string): string => {
    let id = base;
    let n = 2;
    while (usedIds.has(id)) id = `${base}-${n++}`;
    usedIds.add(id);
    return id;
  };
  const flushFaq = () => {
    if (pendingQ) {
      const a = pendingQ.ans.join(" ").replace(/\s+/g, " ").trim();
      if (a && faq.length < 12) faq.push({ q: pendingQ.q, a });
      pendingQ = null;
    }
  };
  const collect = (text: string) => {
    if (pendingQ) pendingQ.ans.push(text);
  };

  while (i < lines.length) {
    const line = lines[i];

    if (!line.trim()) { i++; continue; }

    if (/^---+$/.test(line.trim())) {
      out.push('<hr class="my-8 border-white/[0.08]" />');
      i++;
      continue;
    }

    // Standalone image -> captioned figure.
    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
    if (img) {
      const safe = safeSrc(img[2]);
      if (safe) {
        const alt = esc(img[1]);
        out.push(
          `<figure class="my-7"><img class="${CLS.img}" src="${safe}" alt="${alt}" loading="lazy" />` +
            (alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${alt}</figcaption>` : "") +
            `</figure>`,
        );
        i++;
        continue;
      }
    }

    // Fenced code block.
    if (/^```/.test(line.trim())) {
      const buf: string[] = [];
      i++;
      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
      i++;
      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
      continue;
    }

    // Headings -- anchor id + outline/FAQ capture.
    const hMatch = line.match(/^(#{1,3})\s+(.*)$/);
    if (hMatch) {
      flushFaq();
      const level = hMatch[1].length as 1 | 2 | 3;
      const raw = hMatch[2];
      const text = plainInline(raw);
      const id = uniqueId(slugifyHeading(text));
      const cls = level === 1 ? CLS.h1 : level === 2 ? CLS.h2 : CLS.h3;
      out.push(`<h${level} id="${id}" class="${cls} scroll-mt-28">${inline(raw)}</h${level}>`);
      if (level === 2 || level === 3) toc.push({ id, label: text, level });
      if (text.endsWith("?")) pendingQ = { q: text, ans: [] };
      i++;
      continue;
    }

    // Ordered list.
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
        i++;
      }
      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
      collect(items.map(plainInline).join(". "));
      continue;
    }

    // Unordered list.
    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
        i++;
      }
      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
      collect(items.map(plainInline).join(". "));
      continue;
    }

    // Paragraph.
    const para = [line];
    i++;
    while (
      i < lines.length &&
      lines[i].trim() &&
      !/^#{1,3}\s/.test(lines[i]) &&
      !/^\s*[-*]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !/^```/.test(lines[i].trim()) &&
      !/^---+$/.test(lines[i].trim())
    ) {
      para.push(lines[i]);
      i++;
    }
    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
    collect(plainInline(para.join(" ")));
  }

  flushFaq();
  return { html: out.join("\n"), toc, faq };
}

/* ----------------------------------------------------------------------------
 * Presentation helpers for the editorial post template.
 * ------------------------------------------------------------------------- */

/** 1-2 letter monogram for the byline avatar. */
export function authorInitials(name: string): string {
  const parts = (name || "Nxeon").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "N";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/**
 * A stable, on-brand accent colour for a post -- keyed off the product line the
 * post funnels to, so game guides, hosting guides and domain guides each read a
 * little differently while staying inside Nxeon's navy/violet/cyan family.
 */
export function accentForPost(post: Pick<BlogPost, "category" | "tags" | "title">): string {
  const { href } = productLinkForPost(post as BlogPost);
  const map: Record<string, string> = {
    "/game-servers": "#8b5cf6", // violet
    "/web-hosting": "#3b82f6", // blue
    "/domains": "#22d3ee", // cyan
    "/business-email": "#38bdf8", // sky
    "/vps": "#6f47f5", // brand violet
  };
  return map[href] ?? "#6f47f5";
}

/** Icon name (see components/marketing/icons) that best fits a post's topic. */
export function iconForPost(post: Pick<BlogPost, "category" | "tags" | "title">): string {
  const hay = `${post.category} ${post.tags.join(" ")} ${post.title}`.toLowerCase();
  const has = (...ks: string[]) => ks.some((k) => hay.includes(k));
  if (has("minecraft", "rust", "game", "valheim", "palworld", "ark", "server hosting", "modpack")) return "game";
  if (has("dns", "domain", "nameserver", "whois", "record")) return "globe";
  if (has("email", "mail", "smtp", "spf", "dkim", "imap")) return "mail";
  if (has("security", "firewall", "ssh", "ssl", "vpn", "hardening", "fail2ban", "port")) return "shield";
  if (has("backup", "snapshot", "restore")) return "backup";
  if (has("docker", "linux", "terminal", "command", "cli", "systemd", "bash")) return "terminal";
  if (has("performance", "monitor", "ram", "cpu", "benchmark", "speed", "tune")) return "gauge";
  if (has("web hosting", "wordpress", "website", "php", "nginx")) return "apps";
  if (has("price", "pricing", "cost", "cheap", "compare", "vs", "plan")) return "scale";
  return "server";
}

