(function hl() { const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const LANG = { bash: [['c', /#.*$/], ['s', /"[^"\n]*"/], ['k', /\b(?:sudo|mkdir|cd|apt|docker|compose|certbot|ln|nginx|systemctl|ufw)\b/], ['f', /(?<=\s)-{1,2}[a-z][a-z-]*/]],
    yaml: [['c', /#.*$/], ['s', /"[^"\n]*"/], ['k', /^[ \t]*-?[ \t]*[a-z_]+(?=:)/]],
    nginx: [['c', /#.*$/], ['s', /"[^"\n]*"/], ['v', /\$[a-z_]+/], ['k', /^[ \t]*[a-z_]+(?=[ \t])/], ['n', /\b\d{2,}\b/]] };
  function tokenize(raw, rules) { const master = new RegExp(rules.map(r => `(${r[1].source})`).join('|'), 'gm'); let out = '', last = 0, m;
    while ((m = master.exec(raw))) { if (m[0] === '') { master.lastIndex++; continue; } const gi = m.slice(1).findIndex(x => x !== undefined), cls = rules[gi][0]; out += esc(raw.slice(last, m.index));
      let tok = m[0], lead = ''; if (cls === 'k') { const lm = tok.match(/^[ \t]*-?[ \t]*/); lead = lm ? lm[0] : ''; tok = tok.slice(lead.length); }
      out += esc(lead) + `<span class="tk-${cls}">${esc(tok)}</span>`; last = m.index + m[0].length; }
    return out + esc(raw.slice(last)); }
