"use server";

import { z } from "zod";
import { Prisma } from "@prisma/client";
import { db } from "./db";

export type SubscribeResult = {
  ok: boolean;
  status: "subscribed" | "already" | "error";
  message: string;
};

const emailSchema = z.email();

/**
 * Add an email to the newsletter list. Idempotent: a repeat submission of the
 * same (case-insensitive) address is reported as "already" rather than an error,
 * and the unique constraint is the source of truth against races. No external
 * ESP — we just persist the lead for later export.
 */
export async function subscribe(
  email: string,
  source = "landing",
): Promise<SubscribeResult> {
  const raw = typeof email === "string" ? email.trim().toLowerCase() : "";

  if (!raw) {
    return { ok: false, status: "error", message: "Please enter your email address." };
  }
  if (raw.length > 200) {
    return { ok: false, status: "error", message: "That email address is too long." };
  }

  const parsed = emailSchema.safeParse(raw);
  if (!parsed.success) {
    return { ok: false, status: "error", message: "That doesn’t look like a valid email." };
  }
  const value = parsed.data;

  const cleanSource = (typeof source === "string" ? source.trim() : "").slice(0, 60) || "landing";

  const existing = await db.newsletterSubscriber.findUnique({ where: { email: value } });
  if (existing) {
    return {
      ok: true,
      status: "already",
      message: "You’re already on the list — thanks for sticking around!",
    };
  }

  try {
    await db.newsletterSubscriber.create({ data: { email: value, source: cleanSource } });
  } catch (err) {
    // Unique-constraint race: another request inserted the same email first.
    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === "P2002") {
      return {
        ok: true,
        status: "already",
        message: "You’re already on the list — thanks for sticking around!",
      };
    }
    return {
      ok: false,
      status: "error",
      message: "Something went wrong. Please try again in a moment.",
    };
  }

  return {
    ok: true,
    status: "subscribed",
    message: "You’re in! We’ll send occasional product news — no spam.",
  };
}

import "server-only";
import { db } from "@/lib/db";
import { firstMonthFreeAppliesTo, firstMonthFreeEnabled } from "@/lib/promo-redemption";
import { SUPPORT_REPLY_SENTENCE } from "@/lib/support-promise";
import { annualDiscountPct } from "@/lib/annual-discount";
import { termPriceCents } from "@/lib/billing-terms";
import { liveRegions } from "./lib";

/**
 * Helpers shared by the product pages (web hosting, email, NxCloud, domains,
 * migrate, Matrix, compare hub, vs-DigitalOcean). Everything reads the same
 * modules checkout and the live site use, at request time.
 */

/** The first-month-free offer is granted on shared hosting only, and only
 *  while the admin switch is on — the same gate checkout applies
 *  (lib/order.ts, app/dashboard/deploy). Copy that mentions it follows this. */
export async function hostingPromoActive(): Promise<boolean> {
  return firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
}

/** The one support-response promise (lib/support-promise.ts), with the
 *  design's "Anything else?" lead-in. Replaces the design's "answers around
 *  the clock", which the platform does not promise (OPEN-ITEMS §C). */
export const supportLine = () => `Anything else? ${SUPPORT_REPLY_SENTENCE}`;

const WORDS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve"];
export const numberWord = (n: number) => WORDS[n] ?? String(n);
export const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

/** "A", "A and B", "A, B and C". */
export function andList(xs: string[]) {
  return xs.length <= 1 ? (xs[0] ?? "") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`;
}

/** Regions a customer can deploy into right now (enabled nodes), with their
 *  customer-facing labels, de-duplicated by label (two German facilities are
 *  still "Germany"). Throws when there are none: a page never guesses. */
export async function regionFacts() {
  const regions = await liveRegions();
  if (!regions.length) throw new Error("nxm: no enabled regions");
  const labels = [...new Set(regions.map((r) => r.label))];
  return { regions, labels, count: labels.length, list: andList(labels), word: numberWord(labels.length) };
}

/** Monthly-equivalent price (cents) of a plan on the annual term, exactly as
 *  checkout prices it (termPriceCents with the admin annual discount). */
export async function annualMonthlyCents(monthlyCents: number) {
  const pct = await annualDiscountPct();
