import "server-only";
import fs from "node:fs";
import path from "node:path";
import * as SI from "simple-icons";
import type { BlogPost } from "@prisma/client";
import { GAME_ART_SLUG, GAME_DISPLAY, GAME_FAMILIES, type GameFamily } from "@/lib/games";
import { esc } from "./lib";
import { publicTags } from "./blog-shared";

/**
 * The blog cover visual system (design package: docs/HANDOFF.md §3,
 * source/build_blogvisuals.py, pages/blog-visuals), ported to a server
 * renderer so EVERY post gets a cover from its own fields:
 *
 *  - a post's own `coverImage` wins (except the shared game-server panel
 *    screenshot on a non-game post — OPEN-ITEMS §C "unrelated game-server
 *    panel screenshot inside non-game articles");
 *  - game guides use that game's own art (lib/games.ts GAME_ART_SLUG ->
 *    public/games/art/<slug>_hero.jpg), found from the post's tags/title;
 *  - everything else gets an archetype illustration picked by topic (flow,
 *    terminal, shield, stack, vault, chart, route), filled from the post
 *    itself (its own shell commands, firewall rules, DNS record type, tags),
 *    with official brand logos from its tags (Simple Icons — the package's
 *    _logos.json is a Simple Icons extract) and a palette chosen by category.
 *
 * Covers render in their finished state; ambient motion (flowing lines,
 * travelling packets, blinking cursor, turning dial) plays only while the
 * card is hovered, and never under prefers-reduced-motion. See COVER_CSS.
 */

type Post = Pick<BlogPost, "slug" | "title" | "category" | "tags" | "body" | "coverImage">;

export type Arch = "flow" | "terminal" | "shield" | "stack" | "vault" | "chart" | "route";
export type Cover =
  | { kind: "image"; src: string; source: "post" | "game"; game?: GameFamily }
  | { kind: "art"; arch: Arch; palette: [string, string]; logos: string[]; svg: (uid: string) => string };

// ── palettes by category (the package's CAT map + the real categories) ─────
const PALETTES: Record<string, [string, string]> = {
  security: ["#FFB36B", "#FF5FA8"],
  "self-hosting": ["#9B6BFF", "#3EDCF2"],
  web: ["#3FD89A", "#3EDCF2"],
  networking: ["#4E8DFF", "#3EDCF2"],
  wordpress: ["#4E8DFF", "#9B6BFF"],
  tutorials: ["#3EDCF2", "#9B6BFF"],
  // categories the live blog has that the package didn't draw
  gaming: ["#E04BD6", "#7B5CFF"],
  vps: ["#7B5CFF", "#3EDCF2"],
  domains: ["#3EDCF2", "#3FD89A"],
};
const FALLBACK: [string, string][] = [["#9B6BFF", "#3EDCF2"], ["#4E8DFF", "#9B6BFF"], ["#3FD89A", "#3EDCF2"], ["#E04BD6", "#7B5CFF"]];
function hash(s: string) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}
export function paletteFor(category: string): [string, string] {
  return PALETTES[category.trim().toLowerCase()] ?? FALLBACK[hash(category.toLowerCase()) % FALLBACK.length];
}

// ── game art ────────────────────────────────────────────────────────────────
const norm = (s: string) => s.toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const GAME_KEYS = new Map<string, GameFamily>();
for (const f of GAME_FAMILIES) {
  GAME_KEYS.set(f, f);
  GAME_KEYS.set(norm(GAME_DISPLAY[f].name), f);
  const art = GAME_ART_SLUG[f];
  if (art?.hero) GAME_KEYS.set(art.hero, f);
}
const artCache = new Map<string, boolean>();
function heroFile(f: GameFamily): string | null {
  const slug = GAME_ART_SLUG[f]?.hero;
  if (!slug) return null;
  const rel = `/games/art/${slug}_hero.jpg`;
  if (!artCache.has(rel)) artCache.set(rel, fs.existsSync(path.join(process.cwd(), "public", rel)));
  return artCache.get(rel) ? rel : null;
}
const isGamePost = (p: Post) => /gam(e|ing)/i.test(p.category) || p.tags.some((t) => /game|mods?$/.test(t));

/** The game a post is about: an exact tag match (family key, display name or
 *  art slug), else — for a game post — the full game name in its title. */
export function gameForPost(p: Post): GameFamily | null {
  for (const t of p.tags) {
    const f = GAME_KEYS.get(norm(t));
    if (f) return f;
  }
  if (!isGamePost(p)) return null;
  const title = ` ${p.title.toLowerCase().replace(/['’]/g, "")} `;
  let best: GameFamily | null = null, len = 0;
  for (const f of GAME_FAMILIES) {
    const n = GAME_DISPLAY[f].name.toLowerCase().replace(/['’]/g, "");
    if (n.length > len && new RegExp(`[^a-z0-9]${n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[^a-z0-9]`).test(title)) { best = f; len = n.length; }
  }
  return best;
}
export function gameArt(p: Post): string | null {
  const f = gameForPost(p);
  return f ? heroFile(f) : null;
}

// ── brand logos from tags (Simple Icons) ───────────────────────────────────
const ALIAS: Record<string, string> = { "lets-encrypt": "letsencrypt", certbot: "letsencrypt", bash: "gnubash", env: "dotenv", "claude-code": "claude", node: "nodedotjs", nodejs: "nodedotjs", traefik: "traefikproxy", postgres: "postgresql" };
type Logo = { t: string; hex: string; path: string };
const icons = SI as unknown as Record<string, { title: string; hex: string; path: string } | undefined>;
function logoFor(tag: string): Logo | null {
  const key = ALIAS[tag] ?? tag.replace(/[^a-z0-9]/gi, "").toLowerCase();
  if (!key || GAME_KEYS.has(norm(tag))) return null; // a game's name is never a tech logo (e.g. "rust")
  const ic = icons["si" + key.charAt(0).toUpperCase() + key.slice(1)];
  return ic ? { t: ic.title, hex: ic.hex, path: ic.path } : null;
}
export function logosFor(p: Post): Logo[] {
  const out: Logo[] = [];
  for (const t of publicTags(p.tags)) {
    const l = logoFor(t);
    if (l && !out.some((o) => o.t === l.t)) out.push(l);
  }
  return out;
}
function logo(L: Logo, x: number, y: number, s = 34) {
  return `<g transform="translate(${x},${y})"><rect width="${s + 18}" height="${s + 18}" rx="12" fill="#${L.hex}" fill-opacity=".28" stroke="#fff" stroke-opacity=".25"/><svg x="9" y="9" width="${s}" height="${s}" viewBox="0 0 24 24"><path d="${L.path}" fill="#fff"/></svg></g>`;
}

// ── facts read from the post body ──────────────────────────────────────────
function codeLines(md: string): string[] {
  const out: string[] = [];
  const re = /```[^\n]*\n([\s\S]*?)```/g;
  for (const m of md.matchAll(re)) for (const l of m[1].split("\n")) out.push(l);
  return out;
}
const SHELL = /^(sudo|apt(-get)?|dnf|yum|docker|systemctl|journalctl|ufw|nc|nmap|ss|curl|wget|dig|nslookup|whois|openssl|certbot|ssh|scp|rsync|git|npm|npx|node|python3?|pip|mkdir|cd|ls|cat|tail|df|du|free|htop|top|chmod|chown|crontab|tar|mount|lsblk|mkfs|claude|ping|traceroute|mtr|host|kill|screen|tmux|bash|sh|\.\/)\b/;
/** The post's own shell commands, in order (the terminal archetype types them). */
function commands(md: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of codeLines(md)) {
    const l = raw.trim().replace(/^\$\s+/, "");
    if (!l || l.startsWith("#") || !SHELL.test(l) || seen.has(l)) continue;
    seen.add(l);
    out.push(l.length > 38 ? l.slice(0, 37) + "…" : l);
  }
  return out;
}
/** Firewall rules the post actually writes (`ufw allow 443/tcp` → "allow 443/tcp"). */
function fwRules(md: string): string[] {
  const out: string[] = [];
  for (const m of md.matchAll(/\bufw\s+(allow|deny|limit)\s+([^\s`]+(?:\/\w+)?)/g)) {
    const r = `${m[1]} ${m[2]}`;
    if (!out.includes(r)) out.push(r);
  }
  return out;
}
const RECORD: [RegExp, string][] = [[/\bmx\b/, "MX record"], [/\bcname\b/, "CNAME record"], [/\baaaa\b/, "AAAA record"], [/\btxt\b|\bspf\b|\bdkim\b|\bdmarc\b/, "TXT record"], [/\bns\b|nameserver/, "NS record"]];
const GENERIC = new Set(["tools", "tutorial", "tutorials", "guide", "reference", "developers", "vps", "hosting", "game-servers", "mods", "networking", "security", "linux", "troubleshooting"]);
const titleCase = (s: string) => s.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

// ── archetypes (geometry from build_blogvisuals.py; classes nxc-*) ─────────
function flow(nodes: { label: string; sub?: string; logo?: Logo | null }[]) {
  const xs = [30, 158, 286];
  let out = "";
  nodes.slice(0, 3).forEach((n, i) => {
    const x = xs[i];
    out += `<g${i === 1 ? ' class="nxc-hl"' : ""}><rect x="${x}" y="70" width="86" height="96" rx="16" class="nxc-nd"/>` +
      (n.logo ? logo(n.logo, x + 17, 80, 34) : "") +
      `<text x="${x + 43}" y="${n.logo ? 150 : 124}" class="nxc-nt">${esc(n.label)}</text>` +
      (n.sub ? `<text x="${x + 43}" y="${n.logo ? 162 : 138}" class="nxc-ns">${esc(n.sub)}</text>` : "") + `</g>`;
  });
  return `<path d="M116 118 H158" class="nxc-ln"/><path d="M244 118 H286" class="nxc-ln"/>${out}` +
    `<circle r="4" class="nxc-pk" style="offset-path:path('M116 118 H158')"/><circle r="4" class="nxc-pk nxc-d2" style="offset-path:path('M244 118 H286')"/>`;
}
function terminal(lines: string[], logos: Logo[]) {
  const rows = lines.slice(0, 3).map((l, i) => `<text x="44" y="${96 + i * 20}" class="nxc-tl"><tspan class="nxc-pr">$ </tspan>${esc(l)}</text>`).join("");
  const lg = logos.slice(0, 2).map((n, k) => logo(n, 318 - k * 58, 4, 26)).join("");
  const n = Math.min(lines.length, 3);
  return `<rect x="26" y="56" width="348" height="146" rx="14" class="nxc-win"/><circle cx="44" cy="72" r="4" fill="#FF6A7A"/><circle cx="58" cy="72" r="4" fill="#FFD27A"/><circle cx="72" cy="72" r="4" fill="#3FD89A"/>${rows}<rect x="44" y="${88 + n * 20}" width="8" height="12" class="nxc-cur"/>${lg}`;
}
function shield(rules: string[], logos: Logo[]) {
  const rows = rules.slice(0, 3).map((r, i) => {
    const deny = /^deny/.test(r);
    const t = r.length > 24 ? r.slice(0, 23) + "…" : r;
    return `<g><rect x="186" y="${64 + i * 34}" width="190" height="26" rx="8" class="nxc-rr"/><text x="198" y="${82 + i * 34}" class="nxc-rt">${esc(t)}</text><text x="362" y="${82 + i * 34}" class="nxc-rk${deny ? " nxc-no" : ""}">${deny ? "✕" : "✓"}</text></g>`;
  }).join("");
  const lg = logos.slice(0, 2).map((n, k) => logo(n, 40 + k * 58, 166, 22)).join("");
  return `<path d="M92 44 L148 64 V110 C148 146 124 170 92 182 C60 170 36 146 36 110 V64 Z" class="nxc-sh"/><path d="M72 112 L88 128 L116 96" class="nxc-shc"/>${rows}${lg}`;
}
function vault(logos: Logo[]) {
  const lg = logos.slice(0, 4).map((n, k) => logo(n, 250 + (k % 2) * 64, 50 + Math.floor(k / 2) * 70, 30)).join("");
  let ticks = "";
  for (let a = 0; a < 360; a += 30) ticks += `<line x1="130" y1="58" x2="130" y2="66" transform="rotate(${a} 130 118)" class="nxc-tk"/>`;
  return `<circle cx="130" cy="118" r="70" class="nxc-vd"/><circle cx="130" cy="118" r="52" class="nxc-vd2"/><g class="nxc-dial">${ticks}<circle cx="130" cy="118" r="26" class="nxc-vh"/><rect x="126" y="84" width="8" height="24" rx="4" class="nxc-vh2"/></g>${lg}`;
}
function stack(layers: { label: string; logo?: Logo | null }[]) {
  let out = "";
  layers.slice(0, 4).forEach((l, i) => {
    const y = 180 - i * 40;
    const t = l.label.length > 14 ? l.label.slice(0, 13) + "…" : l.label;
    out += `<g><polygon points="90,${y} 200,${y - 26} 310,${y} 200,${y + 26}" class="nxc-slt"/><polygon points="90,${y} 200,${y + 26} 200,${y + 36} 90,${y + 10}" class="nxc-sll"/><polygon points="200,${y + 26} 310,${y} 310,${y + 10} 200,${y + 36}" class="nxc-slr"/><text x="200" y="${y + 5}" class="nxc-slx">${esc(t)}</text></g>`;
    if (l.logo) out += logo(l.logo, 322, y - 22, 20);
  });
  return out;
}
function route(record: string) {
  return `<rect x="24" y="96" width="120" height="40" rx="20" class="nxc-dom"/><text x="84" y="121" class="nxc-dt">example.com</text>` +
    `<path d="M144 116 C 190 116 190 70 236 70" class="nxc-ln"/><path d="M236 70 C 280 70 280 116 318 116" class="nxc-ln"/>` +
    `<rect x="196" y="50" width="84" height="40" rx="10" class="nxc-rec"/><text x="238" y="68" class="nxc-rt2">${esc(record)}</text><text x="238" y="82" class="nxc-ns2">203.0.113.10</text>` +
    `<circle cx="346" cy="116" r="26" class="nxc-srv"/><text x="346" y="120" class="nxc-dt2">VPS</text>` +
    `<circle r="4" class="nxc-pk" style="offset-path:path('M144 116 C 190 116 190 70 236 70')"/><circle r="4" class="nxc-pk nxc-d2" style="offset-path:path('M236 70 C 280 70 280 116 318 116')"/>` +
    `<circle cx="84" cy="176" r="20" class="nxc-glb"/><path d="M64 176 H104 M84 156 C 74 166 74 186 84 196 C 94 186 94 166 84 156" class="nxc-glb"/>`;
}
function chart(logos: Logo[]) {
  const bars = [60, 96, 132, 84, 110].map((h, i) => `<rect x="${60 + i * 56}" y="${190 - h}" width="34" height="${h}" rx="6" class="nxc-bar${i % 2 ? "" : " nxc-b2"}"/>`).join("");
  return `<line x1="44" y1="190" x2="340" y2="190" class="nxc-ax"/>${bars}` + logos.slice(0, 1).map((n) => logo(n, 300, 30, 34)).join("");
}

// ── topic -> archetype ─────────────────────────────────────────────────────
function pick(p: Post): { arch: Arch; logos: Logo[]; draw: () => string } {
  const tags = publicTags(p.tags);
  const hay = `${p.category} ${tags.join(" ")} ${p.title}`.toLowerCase();
  const has = (...ks: (string | RegExp)[]) => ks.some((k) => (typeof k === "string" ? hay.includes(k) : k.test(hay)));
  const logos = logosFor(p);
  const cmds = commands(p.body);
  const L = (n: string) => logos.find((l) => l.t.toLowerCase().includes(n)) ?? null;
  const body = p.body.toLowerCase();
  const subject = () => {
    const g = gameForPost(p);
    if (g) return { label: GAME_DISPLAY[g].name };
    const t = tags.find((x) => !GENERIC.has(x) && !logoFor(x));
    return t ? { label: titleCase(t) } : logos[0] ? { label: logos[0].t, logo: logos[0] } : { label: p.category };
  };

  if (/\b(best|vs\.?|versus|compared?|comparison|cheapest|benchmark|top \d+)\b/.test(p.title.toLowerCase()) && !isGamePost(p))
    return { arch: "chart", logos, draw: () => chart(logos) };
  if (has("dns", "domain", "nameserver", "whois", "registrar", "a-record", "cname", /\bmx\b/))
    return { arch: "route", logos, draw: () => route(RECORD.find(([re]) => re.test(`${tags.join(" ")} ${p.title.toLowerCase()}`))?.[1] ?? "A record") };
  if (has("reverse-proxy", "reverse proxy", "load balanc", "nginx", "caddy", "traefik", "cloudflare")) {
    const proxy = L("nginx") ?? L("caddy") ?? L("traefik") ?? L("cloudflare");
    const app = logos.find((l) => l !== proxy) ?? null;
    return { arch: "flow", logos, draw: () => flow([{ label: "Browser", sub: "HTTPS" }, { label: proxy?.t ?? "Proxy", sub: ":443 TLS", logo: proxy }, { label: app?.t ?? subject().label, sub: "127.0.0.1", logo: app }]) };
  }
  if (has("migrat"))
    return { arch: "flow", logos, draw: () => flow([{ label: "Old host" }, { label: "Copy", sub: "files + data" }, { label: "Nxeon VPS" }]) };
  if (has("docker", "compose", "container", "volume", "block-storage", "storage", "kubernetes")) {
    const layers: { label: string; logo?: Logo | null }[] = [{ label: "NVMe VPS" }];
    if (/\bubuntu\b/.test(body)) layers.push({ label: "Ubuntu", logo: logoFor("ubuntu") });
    else if (/\bdebian\b/.test(body)) layers.push({ label: "Debian", logo: logoFor("debian") });
    if (/\bdocker\b/.test(body) || has("docker")) layers.push({ label: "Docker", logo: logoFor("docker") });
    const s = subject();
    if (!layers.some((l) => l.label === s.label)) layers.push(s);
    return { arch: "stack", logos, draw: () => stack(layers) };
  }
  if (has("password", "passphrase", "secret", "vault", "bitwarden", "dotenv", "env var", "backup", "encrypt", "entropy"))
    return { arch: "vault", logos, draw: () => vault(logos) };
  if (cmds.length && has("command", "terminal", "cli", "scan", "tune", "disk", "logs", "cron", "ssh", "claude"))
    return { arch: "terminal", logos, draw: () => terminal(cmds, logos) };
  if (has("security", "firewall", "ssl", "tls", "https", "certificate", "harden", "fail2ban", "malware", "ddos", "lets-encrypt")) {
    const fw = fwRules(p.body);
    const rows = fw.length >= 2 ? fw : tags.filter((t) => !logoFor(t)).slice(0, 3);
    return { arch: "shield", logos, draw: () => shield(rows.length ? rows : [p.category.toLowerCase()], logos) };
  }
  if (has("network", "port", "http", "header", "connection", "latency", "ping", "subnet", "cidr", /\bip\b/, "email", "smtp")) {
    const mid = has("firewall", "port", "connection") ? "Firewall" : has("http", "header") ? "HTTP" : has("email", "smtp") ? "Mail" : "Network";
    return { arch: "flow", logos, draw: () => flow([{ label: "Client" }, { label: mid }, { label: "Your VPS" }]) };
  }
  if (cmds.length) return { arch: "terminal", logos, draw: () => terminal(cmds, logos) };
  const layers: { label: string; logo?: Logo | null }[] = [{ label: "NVMe VPS" }];
  if (/\bubuntu\b/.test(body)) layers.push({ label: "Ubuntu", logo: logoFor("ubuntu") });
  const s = subject();
  if (!layers.some((l) => l.label === s.label)) layers.push(s);
  return { arch: "stack", logos, draw: () => stack(layers) };
}

/** A post's own image cover — unless it is the shared game-server panel
 *  screenshot on a non-game post (OPEN-ITEMS §C). */
export function ownCover(p: Post): string | null {
  const c = p.coverImage?.trim();
  if (!c || !/^(https?:\/\/|\/)/.test(c)) return null;
  if (/\/blog\/screenshots\/[^/]*game[^/]*$/i.test(c) && !gameForPost(p) && !isGamePost(p)) return null;
  return c;
}

export function coverFor(p: Post): Cover {
  const own = ownCover(p);
  if (own) return { kind: "image", src: own, source: "post" };
  const g = gameForPost(p);
  const art = g ? heroFile(g) : null;
  if (g && art) return { kind: "image", src: art, source: "game", game: g };
  const { arch, logos, draw } = pick(p);
  const palette = paletteFor(p.category);
  return { kind: "art", arch, palette, logos: logos.map((l) => l.t), svg: (u) => frame(u, palette, draw()) };
}

function frame(u: string, [c1, c2]: [string, string], art: string) {
  let grid = "";
  for (let x = -380; x < 800; x += 40) grid += `<path d="M${x} -300 V525"/>`;
  return `<svg class="nxc" viewBox="0 0 400 225" preserveAspectRatio="xMidYMid meet" style="--c1:${c1};--c2:${c2}" aria-hidden="true" focusable="false"><defs><linearGradient id="${u}g" gradientUnits="userSpaceOnUse" x1="-400" y1="-300" x2="800" y2="525"><stop offset="0" stop-color="${c1}" stop-opacity=".32"/><stop offset="1" stop-color="${c2}" stop-opacity=".22"/></linearGradient>` +
    `<radialGradient id="${u}r" gradientUnits="userSpaceOnUse" cx="360" cy="0" r="380"><stop offset="0" stop-color="${c2}" stop-opacity=".35"/><stop offset="1" stop-color="${c2}" stop-opacity="0"/></radialGradient></defs>` +
    `<rect x="-400" y="-300" width="1200" height="825" fill="url(#${u}g)"/><rect x="-400" y="-300" width="1200" height="825" fill="url(#${u}r)"/><g class="nxc-grid">${grid}</g>${art}</svg>`;
}

/** Cover markup: an <img> (post cover / game art) or the archetype SVG. */
export function coverHtml(c: Cover, uid: string, opts: { eager?: boolean; alt?: string } = {}) {
  if (c.kind === "image")
    return `<img src="${esc(c.src)}" alt="${esc(opts.alt ?? "")}"${opts.eager ? ' fetchpriority="high"' : ' loading="lazy"'} decoding="async">`;
  return c.svg(uid);
}

/**
