@keyframes nxcflow{to{stroke-dashoffset:-22}}@keyframes nxcpk{from{offset-distance:0%}to{offset-distance:100%}}@keyframes nxcblink{50%{opacity:0}}@keyframes nxcspin{to{transform:rotate(200deg)}}@keyframes nxcbar{50%{transform:scaleY(.82)}}
