import "server-only";
import type { BlogPost } from "@prisma/client";
import { formatDate, readMinutes, firstParagraph } from "@/lib/blog";
import { esc } from "./lib";

/**
 * Helpers shared by the new blog hub (/blog) and article template
 * (/blog/[slug]). Everything is computed from the real BlogPost row.
 */

/** Where the new site lives while staged (tools/nxm/nxmlib.py BASE). At
 *  launch BASE becomes "" — change it here too (or move to a shared TS
 *  `staged()` helper; see the blog wiring report). */
export const NXM_BASE = "/nxm";

/** Production routes already ported to the new site (nxmlib ROUTES) — links
 *  to these stay inside the staged site; anything else goes to the live page. */
const PORTED = new Set(["/", "/matrix", "/pricing", "/compare", "/vps-vs-digitalocean", "/vps", "/web-hosting", "/business-email", "/domains",
  "/migrate", "/nxcloud", "/free-vps", "/free-minecraft", "/game-servers", "/valheim-server-hosting", "/minecraft-server-hosting",
  "/singapore-vps-hosting", "/germany-vps-hosting", "/wordpress-vps-hosting", "/docker-hosting", "/mods", "/blog", "/contact"]);
export function staged(href: string): string {
  const m = href.match(/^(\/[^?#]*)?(.*)$/);
  const p = m?.[1] ?? "";
  if (!p) return href;
  if (PORTED.has(p) || p.startsWith("/blog/") || p.startsWith("/minecraft-server-hosting/"))
    return NXM_BASE + (p === "/" ? "" : p) + (m?.[2] ?? "");
  return href;
}
export const postHref = (slug: string) => staged(`/blog/${encodeURIComponent(slug)}`);

/** Internal tags never shown publicly: `seobatch` marks the SEO batch import
 *  (OPEN-ITEMS §C); `start-here` is the editor's pin for the hub's "Start
 *  here" list. */
const INTERNAL_TAGS = new Set(["seobatch", "start-here"]);
export const publicTags = (tags: string[]) => tags.map((t) => t.trim().toLowerCase()).filter((t) => t && !INTERNAL_TAGS.has(t));

/** The design names the Gaming category "Game servers" on the hub. */
export const categoryLabel = (c: string) => (c.trim().toLowerCase() === "gaming" ? "Game servers" : c);

export const published = (p: Pick<BlogPost, "publishedAt" | "createdAt">) => p.publishedAt ?? p.createdAt;
/** "Aug 16, 2026" — the hub card date format in the design. */
export const shortDate = (d: Date) => d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" });
export const longDate = (d: Date) => formatDate(d);
export const readLabel = (body: string) => `${readMinutes(body)} min read`;
export const excerptOf = (p: Pick<BlogPost, "excerpt" | "body">) => (p.excerpt?.trim() || firstParagraph(p.body));

export { esc };

