import "server-only";
import { db } from "@/lib/db";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { gameTiers, introSpan, usd, vpsPlans } from "./lib";

/**
 * The article's product CTA facts for the page `productLinkForPost` picks —
 * a real "from" price and one real spec line, read from the same tables and
 * helpers checkout uses. Null when the product has nothing orderable (the
 * panel then shows no price rather than a stale one).
 */
export type ProductFacts = { from: string; spec: string | null };

const money = (dollars: number) => usd(Math.round(dollars * 100));
const fromLine = (p: number, i: number | null, it: number | null) =>
  i != null ? `From ${money(i)} for the ${introSpan(it)}, then ${money(p)} a month` : `From ${money(p)} a month`;

export async function productFacts(href: string, game: GameFamily | null): Promise<ProductFacts | null> {
  switch (href) {
    case "/vps": {
      const plans = await vpsPlans();
      if (!plans.length) return null;
      const c = plans.reduce((a, b) => (b.p < a.p ? b : a));
      return { from: fromLine(c.p, c.i, c.it), spec: `${c.n}: ${c.cpu} vCPU, ${c.ram} GB RAM, ${c.disk} GB NVMe` };
    }
    case "/game-servers": {
      // the game the guide is about, when we host it; otherwise every game
      let tiers = game ? await gameTiers(game) : [];
      const named = tiers.length > 0;
      if (!named) tiers = await gameTiers();
      if (!tiers.length) return null;
      const c = tiers.reduce((a, b) => ((b.i ?? b.p) < (a.i ?? a.p) ? b : a));
      const name = named && game ? GAME_DISPLAY[game].name : null;
      return {
        from: fromLine(c.p, c.i, c.it) + (name ? ` for ${name}` : ""),
        spec: `${c.ram} GB RAM${c.slots ? `, ${c.slots} player slots` : ""}${named ? "" : ` (${c.name})`}`,
      };
    }
    case "/web-hosting": {
      const h = await db.hostingPlan.findFirst({ where: { active: true }, orderBy: { priceCents: "asc" } });
      return h ? { from: `From ${usd(h.priceCents)} a month`, spec: `${h.name}: ${h.maxSites} site${h.maxSites === 1 ? "" : "s"}, ${h.diskGB} GB storage` } : null;
    }
    case "/business-email": {
      const plans = await db.emailPlan.findMany({ where: { active: true } });
      if (!plans.length) return null;
      const per = (p: (typeof plans)[number]) => p.priceCents / Math.max(1, p.termMonths);
      const c = plans.reduce((a, b) => (per(b) < per(a) ? b : a));
      return { from: `From ${usd(Math.round(per(c)))} a month`, spec: `${c.name}: ${c.mailboxes} mailbox${c.mailboxes === 1 ? "" : "es"}, ${c.storageGB} GB each` };
    }
    case "/domains": {
      const c = POPULAR_TLDS.reduce((a, b) => (b.fromCents < a.fromCents ? b : a));
      const com = POPULAR_TLDS.find((t) => t.tld === ".com");
      return { from: `Domains from ${usd(c.fromCents)} a year (${c.tld})`, spec: com && com !== c ? `.com from ${usd(com.fromCents)} a year` : null };
    }
  }
  return null;
}

