import "server-only";
import { notFound } from "next/navigation";
import type { BlogPost } from "@prisma/client";
import {
  APP_URL, authorInitials, firstParagraph, getPublishedPost, getRelatedPosts, iconForPost, productLinkForPost, renderArticle,
  type RenderedArticle,
} from "@/lib/blog";
import { SUPPORT_REPLY_WITHIN } from "@/lib/support-promise";
import type { NxmLoad } from "./lib";
import { coverCss, coverFor, coverHtml, gameForPost, paletteFor } from "./blog-covers";
import { productFacts } from "./blog-product";
import { NXM_BASE, categoryLabel, esc, longDate, postHref, publicTags, published, readLabel, staged } from "./blog-shared";

/**
 * /blog/[slug] — the Vaultwarden design is the template for every published
 * post. Everything comes from the post row and the blog helpers the live
 * article uses: body/TOC/FAQ from renderArticle, related from getRelatedPosts,
 * the product panel from productLinkForPost with a real "from" price, author /
 * dates / read time from the row, the cover from the cover system. Unknown or
 * unpublished slug -> 404.
 */

async function post(p: Record<string, string>): Promise<BlogPost> {
  const slug = (p.slug ?? "").trim();
  const row = slug ? await getPublishedPost(slug) : null;
  if (!row) notFound();
  return row;
}

const abs = (u: string) => (u.startsWith("http") ? u : `${APP_URL}${u}`);
/** A raster image for social cards / BlogPosting.image: the post's own cover,
 *  else its game's art. (Archetype covers are SVG — the site-wide OG image
 *  applies then.) */
function rasterCover(row: BlogPost) {
  const c = coverFor(row);
  return c.kind === "image" ? abs(c.src) : undefined;
}

export async function meta(p: Record<string, string>) {
  const row = await post(p);
  const title = row.seoTitle || row.title;
  const description = row.seoDescription || row.excerpt || `${row.title} — a guide from the Nxeon blog.`;
  return { title, description, image: rasterCover(row), type: "article" as const };
}

// ── article body: renderArticle's HTML in the design's markup ─────────────
const unescape = (s: string) => s.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&amp;/g, "&");
const SHELL = /^\s*(\$ |sudo |apt(-get)? |docker |systemctl |ufw |nc |nmap |ss |curl |wget |dig |nslookup |whois |openssl |certbot |ssh |git |npm |mkdir |cd |ls |cat |df |du |chmod |chown |crontab |tar |ping |claude|\.\/|#!)/m;
function langOf(code: string): { lang: string; label: string } {
  const t = unescape(code);
  if (/^\s*(server|location|upstream|http)\b[^\n]*\{|proxy_pass|listen\s+\d+/m.test(t)) return { lang: "nginx", label: "nginx" };
  if (SHELL.test(t)) return { lang: "bash", label: "terminal" };
  if (/^\s*[\[{]/.test(t) && /[\]}]\s*$/.test(t) && /"\s*:/.test(t)) return { lang: "json", label: "json" };
  if ((t.match(/^\s*-?\s*[A-Za-z_][\w.-]*:(\s|$)/gm) ?? []).length >= 2) return { lang: "yaml", label: "yaml" };
  return { lang: "text", label: "code" };
}
const APP_HOST = (() => {
  try { return new URL(APP_URL).host.replace(/^www\./, ""); } catch { return "nxeon.cloud"; }
})();

function articleHtml(r: RenderedArticle, gamePost: boolean) {
  let h = r.html;
  // 1. the live renderer's Tailwind classes → plain elements styled by the design (`.art …`)
  h = h.replace(/<([a-z0-9]+)((?:\s[^<>]*)?)>/g, (_m, tag: string, attrs: string) =>
    `<${tag}${attrs.replace(/\s+class="[^"]*"/g, "")}>`);
  // 2. code blocks → the design's terminal cards (copy button + highlighting)
  h = h.replace(/<pre><code>([\s\S]*?)<\/code><\/pre>/g, (_m, code: string) => {
    const { lang, label } = langOf(code);
    return `<figure class="cb" data-lang="${lang}"><figcaption class="cb-h"><span class="cb-dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="cb-f">${label}</span><span class="cb-l">${lang === "text" ? "" : lang}</span><button type="button" class="cb-copy" aria-label="Copy code">Copy</button></figcaption><pre><code>${code}</code></pre></figure>`;
  });
  // 3. OPEN-ITEMS §C: no game-server panel screenshot inside a non-game article
  if (!gamePost) h = h.replace(/<figure>\s*<img[^>]*src="\/blog\/screenshots\/[^"]*game[^"]*"[^>]*>[\s\S]*?<\/figure>/gi, "");
  // 4. links to the site stay on the staged site (relative, same tab)
  h = h.replace(/<a href="([^"]*)"([^>]*)>/g, (_m, href: string, rest: string) => {
    let u = href;
    const m = u.match(/^https?:\/\/(?:www\.)?([^/]+)(\/[^"]*)?$/);
    if (m && (m[1] === APP_HOST || m[1] === "nxeon.cloud")) { u = m[2] || "/"; rest = rest.replace(/\s+target="_blank"|\s+rel="[^"]*"/g, ""); }
    if (u.startsWith("/")) u = staged(u);
    return `<a href="${u}"${rest}>`;
  });
  return h;
}

