    `<a class="nxm-btn${DEPLOY.has(product.href) ? " au-hov" : ""}" href="${esc(pHref)}"><span class="nxm-bt">${esc(cta)}<span class="ar">→</span></span></a><small>Support replies ${esc(SUPPORT_REPLY_WITHIN)}</small></div>`;

  const toc = r.toc.map((t) => `<li${t.level === 3 ? ' class="l3"' : ""}><a href="#${esc(t.id)}">${esc(t.label)}</a></li>`).join("");

