import { CONTACT_CATEGORIES, type ContactCategory } from "@/lib/contact-categories";

/**
 * The new contact page's topics, mapped onto the REAL contact categories
 * (lib/contact-categories.ts: support | bug | sales | billing | general),
 * which decide the mailbox a message is routed to (support@ / admin@ /
 * contact@).
 *
 *  - The design's five topic buttons ARE the five real categories.
 *  - Its "What are you planning?" choices under Sales (and the matching
 *    `?topic=` deep links: vps | game | custom | migrate | partner) are all
 *    sales enquiries — they route to `sales` (contact@) and the choice is
 *    written into the message so the team sees it.
 *  - `?topic=sales|support|billing|bug|general` select that category.
 */
export const CONTACT_PLANS = {
  vps: "Cloud VPS",
  game: "Game servers",
  custom: "Custom server for a big community",
  migrate: "A free migration",
  partner: "A partnership",
} as const;
