import "server-only";
import { supportEmail } from "@/lib/settings";
import { SUPPORT_REPLY_WITHIN } from "@/lib/support-promise";
import { CONTACT_CATEGORIES } from "@/lib/contact-categories";
import type { NxmLoad } from "./lib";
import { NXM_BASE } from "./blog-shared";
import { CONTACT_PLANS } from "./contact-topics";

/**
 * /contact — the design's routed form, wired to the real contact backend
 * (POST ${NXM_BASE}/api/contact -> lib/actions-contact.ts submitContact:
 * same validation, rate limit, honeypot, mailbox routing and ContactMessage
 * row as the live form). The support address is the `support_email`
 * setting; the reply promise is lib/support-promise.ts — the one the live
 * contact page and the contact action's own confirmation use.
 */
export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const email = await supportEmail();
  const slots: Record<string, string> = {
    "support.email": email,
    "support.within": SUPPORT_REPLY_WITHIN,
    "contact.api": `${NXM_BASE}/api/contact`,
    // result of a no-JavaScript submission (the route redirects back here)
    "contact.notice:html": p.sent === "1"
      ? `<p class="cnf-note ok" role="status">Thanks — your message is on its way. We’ll reply ${SUPPORT_REPLY_WITHIN}.</p>`
      : p.error ? `<p class="cnf-note" role="alert">${p.error.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`).slice(0, 300)}</p>` : "",
  };
  for (const [k, c] of Object.entries(CONTACT_CATEGORIES)) {
    slots[`cat.${k}.label`] = c.label;
    slots[`cat.${k}.hint`] = c.hint;
  }
  for (const [k, v] of Object.entries(CONTACT_PLANS)) slots[`plan.${k}`] = v;
  return { slots, data: { api: `${NXM_BASE}/api/contact`, email } };
}

