import { submitContact } from "@/lib/actions-contact";
import { CONTACT_EXTRAS, CONTACT_PLANS, topicToCategory } from "../../_data/contact-topics";
import { NXM_BASE } from "../../_data/blog-shared";
import { rejectRequest } from "../_guard";

/**
 * POST /nxm/api/contact — the new contact page's form -> the REAL contact
 * backend. The design's form is static markup + page JS, so it can't call the
 * `submitContact` server action directly; this handler is the bridge and adds
 * nothing of its own to the policy: validation (Zod), the 5-per-10-minutes
 * rate limit, the honeypot, mailbox routing and the ContactMessage row are all
 * `submitContact`'s. It only maps the design's topic/plan onto a real
 * category (see _data/contact-topics.ts) and folds the design's extra context
 * fields into the message.
 *
 * JSON in -> JSON { ok, message } out (the page renders it). A plain form post
 * (no JavaScript) is redirected back to the page with ?sent=1 / ?error=1.
 */
export const dynamic = "force-dynamic";

const str = (v: unknown, max = 5000) => (typeof v === "string" ? v.slice(0, max) : "");

export async function POST(req: Request) {
  const bad = rejectRequest(req);
  if (bad) return bad;

  const ctype = req.headers.get("content-type") ?? "";
  const isForm = ctype.includes("application/x-www-form-urlencoded") || ctype.includes("multipart/form-data");
  let raw: Record<string, unknown> = {};
  try {
    const text = await req.text();
    if (text.length > 20_000) return Response.json({ ok: false, message: "That message is too long." }, { status: 413 });
    raw = isForm ? Object.fromEntries(new URLSearchParams(text)) : (JSON.parse(text || "{}") as Record<string, unknown>);
  } catch {
    return Response.json({ ok: false, message: "Please check the form and try again." }, { status: 400 });
  }
  if (!raw || typeof raw !== "object") raw = {};

  const mapped = topicToCategory(str(raw.plan, 20) || str(raw.topic, 20)) ?? topicToCategory(str(raw.topic, 20));
  const category = mapped?.category ?? "general";
  const plan = category === "sales" ? (topicToCategory(str(raw.plan, 20))?.plan ?? mapped?.plan ?? null) : null;
  const typed = str(raw.message ?? raw.msg).trim();

  // The contact schema's own minimum, checked on what the customer typed —
  // otherwise the context lines below could satisfy it for an empty message.
  let result;
  if (typed.length < 10) {
    result = { ok: false, message: "Please add a little more detail (at least 10 characters)." };
  } else {
    const context = [
      ...(plan ? [`Planning: ${CONTACT_PLANS[plan]}`] : []),
      ...CONTACT_EXTRAS.filter((x) => x.for === "any" || x.for === category)
        .map((x) => [x.label, str(raw[x.key], 200).trim()] as const)
        .filter(([, v]) => v)
        .map(([l, v]) => `${l}: ${v}`),
    ];
    const message = (context.length ? `${context.join("\n")}\n\n` : "") + typed;
    result = await submitContact({
      name: str(raw.name, 200),
      email: str(raw.email, 300),
      category,
      message: message.slice(0, 5000),
      company: str(raw.company, 200), // the hidden honeypot field (the visible company field is `org`)
    });
  }

  if (isForm) {
    const back = new URL(`${NXM_BASE}/contact`, req.url);
    back.searchParams.set(result.ok ? "sent" : "error", "1");
    return Response.redirect(back, 303);
  }
  return Response.json(result, { status: result.ok ? 200 : 422, headers: { "cache-control": "no-store" } });
}

