/**
 * Shared guard for the new marketing site's form endpoints (app/nxm/api/*):
 *  - staging only, like the rest of /nxm (app/nxm/layout.tsx) — route
 *    handlers don't pass through that layout, so they check it themselves;
 *  - same-origin only: a browser POST from another site is refused (the
 *    check Next applies to server actions, which these endpoints stand in for).
 */
export function rejectRequest(req: Request): Response | null {
  if (process.env.NXEON_ENV !== "staging") return new Response("Not found", { status: 404 });
  const origin = req.headers.get("origin");
  if (origin) {
    const host = req.headers.get("x-forwarded-host") ?? req.headers.get("host");
    let ok = false;
    try { ok = !!host && new URL(origin).host === host; } catch { ok = false; }
    if (!ok) return Response.json({ ok: false, message: "Cross-site request refused." }, { status: 403 });
  }
  return null;
}

