/* ============ Contact ============ */
(function contact() {
  const TEAM = { sales: 'the sales team', support: 'technical support', billing: 'the billing team', bug: 'the platform team', general: 'the team' };
  let topic = 'sales', plan = '';
  const setTopic = t => { topic = t; $$('.cnt').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.t === t))); $$('.cnx').forEach(x => x.hidden = x.dataset.for !== t); $('#cn-team').textContent = TEAM[t]; };
  const setPlan = v => { plan = plan === v ? '' : v; $$('.cnc').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.v === plan))); $('#cn-scale').hidden = !['custom', 'game', 'migrate'].includes(plan); };
  $$('.cnt').forEach(b => b.addEventListener('click', () => setTopic(b.dataset.t)));
  $$('.cnc').forEach(b => b.addEventListener('click', () => setPlan(b.dataset.v)));
  /* deep links: ?topic=custom|sales|support|billing|bug|general, or #custom */
  const q = new URLSearchParams(location.search).get('topic') || location.hash.replace('#', '');
  if (['custom', 'migrate', 'partner', 'vps', 'game'].includes(q)) { setTopic('sales'); setPlan(q); } else if (TEAM[q]) setTopic(q);
  $('#cn-copy').addEventListener('click', async e => { try { await navigator.clipboard.writeText('support@nxeon.cloud'); } catch (_) {} e.target.textContent = 'Copied'; setTimeout(() => e.target.textContent = 'Copy', 1500); });
  const f = $('#cnf'), err = $('#cnf-err');
  f.addEventListener('input', e => e.target.closest('.cnl')?.classList.remove('bad'));
  f.addEventListener('submit', e => { e.preventDefault(); const bad = [];
    ['name', 'email', 'msg'].forEach(n => { const el = f.elements[n], ok = el.value.trim() && (n !== 'email' || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(el.value.trim())); el.closest('.cnl').classList.toggle('bad', !ok); if (!ok) bad.push(el); });
    if (bad.length) { err.hidden = false; err.textContent = bad.length === 1 && bad[0].name === 'email' && bad[0].value ? 'That email address doesn’t look quite right.' : 'Please fill in your name, email and message.'; bad[0].focus(); return; }
    err.hidden = true; const extra = topic !== 'sales' ? '' : plan === 'custom' ? ' about a custom server' : plan === 'migrate' ? ' about your migration' : '';
    $('#cnd-t').textContent = `It’s with ${TEAM[topic]}${extra}. We’ll reply to ${f.elements.email.value.trim()} within one business day.`;
    f.hidden = true; $('#cnd').hidden = false; $('#cnd').scrollIntoView({ behavior: RM ? 'auto' : 'smooth', block: 'center' }); });
  $('#cnd-new').addEventListener('click', () => { f.reset(); setPlan(plan); setTopic('sales'); $('#cnd').hidden = true; f.hidden = false; });
})();

})();

