const plain = (h: string) => unescape(h.replace(/<[^>]+>/g, " ")).replace(/\\s+/g, " ").trim();
/**
 * The post's FAQ section -> the design's accordion (`.faq details`). The
 * section is an h2 "FAQ" / "FAQs" / "Frequently asked questions"; its
 * questions are either h3 headings (what renderArticle also lifts into FAQ
 * JSON-LD) or paragraphs that open with a bold question. Each <details> keeps
 * the heading's id so TOC/anchor links still land. A comment sits before
 * <summary> (valid: summary stays the first child element) so NxmPage's
 * details-based FAQ extraction doesn't emit a second FAQPage — the article's
 * FAQPage comes from renderArticle, exactly as on the live page.
 */
function faqAccordion(h: string): { html: string; ids: Set<string>; extra: { q: string; a: string }[] } {
  const ids = new Set<string>();
  const extra: { q: string; a: string }[] = [];
  const m = h.match(/<h2 id="([^"]*)">\\s*(?:FAQs?|Frequently asked questions)\\s*<\\/h2>/i);
  if (!m || m.index == null) return { html: h, ids, extra };
  const start = m.index + m[0].length;
  const next = h.indexOf("<h2", start);
  const end = next < 0 ? h.length : next;
  const sec = h.slice(start, end);
  const item = (id: string | null, q: string, a: string) =>
    `<details${id ? ` id="${id}"` : ""}><!--faq--><summary>${q}</summary>${a}</details>`;
  let lead = "", items: string[] = [];
  if (/<h3 id="/.test(sec)) {
    const parts = sec.split(/(?=<h3 id=")/);
    lead = parts[0].startsWith("<h3") ? "" : parts.shift() ?? "";
    items = parts.map((part) => {
      const hm = part.match(/^<h3 id="([^"]*)">([\\s\\S]*?)<\\/h3>([\\s\\S]*)$/);
      if (!hm) return part;
      ids.add(hm[1]);
      return item(hm[1], hm[2], hm[3]);
    });
  } else {
    const re = /<p><strong>([^<]*\\?)<\\/strong>\\s*([\\s\\S]*?)<\\/p>/g;
    let last = 0, mm: RegExpExecArray | null;
    while ((mm = re.exec(sec))) {
      if (!items.length) lead = sec.slice(0, mm.index);
      else if (mm.index > last) items[items.length - 1] = items[items.length - 1].replace(/<\\/details>$/, sec.slice(last, mm.index) + "</details>");
      items.push(item(null, mm[1], mm[2] ? `<p>${mm[2]}</p>` : ""));
      extra.push({ q: plain(mm[1]), a: plain(mm[2]) });
      last = re.lastIndex;
    }
    if (!items.length) return { html: h, ids, extra };
    items[items.length - 1] = items[items.length - 1].replace(/<\\/details>$/, sec.slice(last) + "</details>");
  }
  if (!items.length) return { html: h, ids, extra };
  items[0] = items[0].replace(/^<details/, "<details open");
  return { html: h.slice(0, start) + lead + `<div class="faq art-faq">${items.join("")}</div>` + h.slice(end), ids, extra };
}
