const { chromium } = require('/opt/nxeon/node_modules/playwright');
(async () => {
  const b = await chromium.launch();
  for (const rm of ['no-preference', 'reduce']) {
    const ctx = await b.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: rm });
    const p = await ctx.newPage();
    await p.goto('http://localhost:3033/nxm/blog?category=Networking', { waitUntil: 'networkidle', timeout: 180000 });
    await p.waitForTimeout(1500);
    const card = p.locator('.bh-c:has(.nxc)').first();
    const st = () => card.evaluate(c => { const ln = c.querySelector('.nxc-ln'), pk = c.querySelector('.nxc-pk'); return { ln: ln && getComputedStyle(ln).animationName, pk: pk && getComputedStyle(pk).animationName, pkPath: pk && getComputedStyle(pk).offsetPath }; });
    console.log(rm, 'rest', JSON.stringify(await st()));
    await card.scrollIntoViewIfNeeded(); await card.hover(); await p.waitForTimeout(400);
    console.log(rm, 'hover', JSON.stringify(await st()));
    await ctx.close();
  }
  await b.close();
})();
EOF
sleep 5; cd /tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad && timeout 300 node blogwire-motion.js

