S=/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad && cat > $S/blogwire-cov.ts <<'EOF'
import { db } from "/root/nxeon-worktrees/marketing-nxm/lib/db";
import { coverFor } from "/root/nxeon-worktrees/marketing-nxm/app/nxm/_data/blog-covers";
(async () => {
  const posts = await db.blogPost.findMany({ where: { published: true }, orderBy: { publishedAt: "desc" } });
  const tally: Record<string, number> = {};
  for (const p of posts) {
    const c = coverFor(p);
    const k = c.kind === "image" ? `image:${c.source}` : `art:${c.arch}`;
    tally[k] = (tally[k] ?? 0) + 1;
    console.log(k.padEnd(16), (c.kind === "image" ? c.src : `${c.palette.join("/")} logos=[${c.logos.join(",")}]`).padEnd(44), p.slug);
  }
  console.log(tally);
  await db.$disconnect();
})();
EOF
timeout 120 node --conditions=react-server --import tsx $S/blogwire-cov.ts 2>&1 | tail -40

